<?php
namespace Tests\Feature;use App\Models\{Institution,Survey,User};use Database\Seeders\RolesAndPermissionsSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class HeatmapGenerationTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(RolesAndPermissionsSeeder::class);}public function test_idw_heatmap_is_generated_from_valid_real_measurements():void{$u=User::factory()->create();$u->assignRole('Network Admin');$i=Institution::create(['name'=>'T','slug'=>'t']);$c=$i->campuses()->create(['name'=>'M','code'=>'M']);$b=$c->buildings()->create(['name'=>'B','code'=>'B']);$f=$b->floors()->create(['name'=>'G','code'=>'G','level_number'=>0]);$fp=$f->floorPlans()->create(['uploaded_by'=>$u->id,'original_name'=>'p.png','file_path'=>'p','mime_type'=>'image/png','file_size'=>1,'original_width'=>1000,'original_height'=>800,'pixels_per_metre'=>50,'usable_boundary'=>[['x'=>0,'y'=>0],['x'=>1,'y'=>0],['x'=>1,'y'=>1],['x'=>0,'y'=>1]],'version'=>1,'is_active'=>true]);$s=Survey::create(['floor_id'=>$f->id,'floor_plan_id'=>$fp->id,'created_by'=>$u->id,'name'=>'S','minimum_points'=>3]);foreach([[.1,.1,-50],[.9,.1,-65],[.5,.9,-80]] as[$x,$y,$v]){$p=$s->points()->create(['floor_plan_id'=>$fp->id,'captured_by'=>$u->id,'x_normalized'=>$x,'y_normalized'=>$y,'source_type'=>'measured','collection_method'=>'manual','validation_status'=>'valid','captured_at'=>now()]);$p->measurements()->create(['rssi_dbm'=>$v,'source_type'=>'measured','collection_method'=>'manual','captured_at'=>now()]);}$this->actingAs($u)->postJson("/api/surveys/{$s->id}/heatmaps",['grid_width'=>20,'grid_height'=>20])->assertCreated()->assertJson(['status'=>'completed','source_point_count'=>3,'algorithm'=>'idw']);$this->assertDatabaseHas('heatmap_runs',['survey_id'=>$s->id,'status'=>'completed']);}}
